void ota_page_update_language(lang_type_t lang)
{
    aic_set_language(lang);
    ota_page_update_current_language();
}

void ota_page_update_current_language()
{
    ota_page_t *scr = ota_page_get(&ui_manager);
    if (!scr || !scr->obj)
        return;

    lv_obj_set_style_text_font(scr->uuid_lab, aic_get_multi_lang_font(16), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(scr->uuid_lab, aic_get_translation(uuid));

    lv_obj_set_style_text_font(scr->bt_lab, aic_get_multi_lang_font(16), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(scr->bt_lab, aic_get_translation(ota_bluetooth));

    lv_obj_set_style_text_font(scr->ota_lab, aic_get_multi_lang_font(16), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(scr->ota_lab, aic_get_translation(ota_ota));

    lv_obj_set_style_text_font(scr->sn_lab, aic_get_multi_lang_font(16), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(scr->sn_lab, aic_get_translation(ota_sn));

    lv_obj_set_style_text_font(scr->version_lab, aic_get_multi_lang_font(16), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(scr->version_lab, aic_get_translation(ota_version));


}
